#!/bin/bash
cd /testbed
source /opt/conda/bin/activate testbed

# H2: fail if any test file or test config differs from the base commit plus the test patch.
check_test_integrity() (
    index_dir=$(mktemp -d) &&
        export GIT_INDEX_FILE=$index_dir/index GIT_NO_REPLACE_OBJECTS=1 &&
        git read-tree 046dfa51f0989c7f55cf6d7dd00ba71f3ec5a115 &&
        git apply --cached /tests/upstream_tests.patch &&
        git diff --quiet --no-ext-diff -- ':(literal)tests/test_types_enum.py' ':(literal)tests/test_types_flag.py' ':(literal)tests/test_utils.py' ':(glob)**/conftest.py' ':(glob)**/pytest.ini' ':(glob)**/.pytest.ini' ':(glob)**/pytest.toml' ':(glob)**/.pytest.toml' ':(glob)**/setup.cfg' ':(glob)**/tox.ini' ':(glob)**/pyproject.toml' ':(glob)**/sitecustomize.py' ':(glob)**/usercustomize.py' ':(glob)**/test/**' ':(glob)**/tests/**' &&
        test -z "$(git ls-files --others -- ':(literal)tests/test_types_enum.py' ':(literal)tests/test_types_flag.py' ':(literal)tests/test_utils.py' ':(glob)**/conftest.py' ':(glob)**/pytest.ini' ':(glob)**/.pytest.ini' ':(glob)**/pytest.toml' ':(glob)**/.pytest.toml' ':(glob)**/setup.cfg' ':(glob)**/tox.ini' ':(glob)**/pyproject.toml' ':(glob)**/sitecustomize.py' ':(glob)**/usercustomize.py')" &&
        test -z "$(git ls-files --others -- ':(glob)**/test/**/*.py' ':(glob)**/test/**/*.pyc' ':(glob)**/test/**/*.so' ':(glob)**/tests/**/*.py' ':(glob)**/tests/**/*.pyc' ':(glob)**/tests/**/*.so' ':(exclude,glob)**/test_*.py' ':(exclude,glob)**/*_test.py' ':(exclude,glob)**/__pycache__/**')"
)

mkdir -p /logs/verifier
if check_test_integrity && pytest --no-header -rA --tb=line --color=no -p no:cacheprovider -W ignore::DeprecationWarning 'tests/test_types_enum.py::test_enum_str_repr_in_struct[True]' 'tests/test_types_enum.py::test_enum_str_repr_in_struct[False]' 'tests/test_types_flag.py::test_flag_str_repr_in_struct[True]' 'tests/test_types_flag.py::test_flag_str_repr_in_struct[False]' 'tests/test_utils.py::test_dumpstruct_enum[True]' 'tests/test_utils.py::test_dumpstruct_enum[False]' tests/test_types_enum.py::test_enum tests/test_types_enum.py::test_enum_read tests/test_types_enum.py::test_enum_write tests/test_types_enum.py::test_enum_array_read tests/test_types_enum.py::test_enum_array_write tests/test_types_enum.py::test_enum_alias tests/test_types_enum.py::test_enum_bad_type tests/test_types_enum.py::test_enum_eof 'tests/test_types_enum.py::test_enum_same_value_different_type[True]' 'tests/test_types_enum.py::test_enum_same_value_different_type[False]' tests/test_types_enum.py::test_enum_str_repr 'tests/test_types_enum.py::test_enum_struct[True]' 'tests/test_types_enum.py::test_enum_struct[False]' tests/test_types_enum.py::test_enum_comments 'tests/test_types_enum.py::test_enum_name[True]' 'tests/test_types_enum.py::test_enum_name[False]' 'tests/test_types_enum.py::test_enum_struct_write[True]' 'tests/test_types_enum.py::test_enum_struct_write[False]' 'tests/test_types_enum.py::test_enum_anonymous[True]' 'tests/test_types_enum.py::test_enum_anonymous[False]' 'tests/test_types_enum.py::test_enum_anonymous_struct[True]' 'tests/test_types_enum.py::test_enum_anonymous_struct[False]' 'tests/test_types_enum.py::test_enum_reference_own_member[True]' 'tests/test_types_enum.py::test_enum_reference_own_member[False]' tests/test_types_flag.py::test_flag tests/test_types_flag.py::test_flag_read tests/test_types_flag.py::test_flag_write tests/test_types_flag.py::test_flag_array_read tests/test_types_flag.py::test_flag_array_write tests/test_types_flag.py::test_flag_operator tests/test_types_flag.py::test_flag_str_repr tests/test_types_flag.py::test_flag_struct 'tests/test_types_flag.py::test_flag_struct_read[True]' 'tests/test_types_flag.py::test_flag_struct_read[False]' 'tests/test_types_flag.py::test_flag_anonymous[True]' 'tests/test_types_flag.py::test_flag_anonymous[False]' 'tests/test_types_flag.py::test_flag_anonymous_struct[True]' 'tests/test_types_flag.py::test_flag_anonymous_struct[False]' tests/test_utils.py::test_hexdump 'tests/test_utils.py::test_dumpstruct[True]' 'tests/test_utils.py::test_dumpstruct[False]' 'tests/test_utils.py::test_dumpstruct_anonymous[True]' 'tests/test_utils.py::test_dumpstruct_anonymous[False]' tests/test_utils.py::test_pack_unpack tests/test_utils.py::test_swap; then
    echo 1 > /logs/verifier/reward.txt
else
    echo 0 > /logs/verifier/reward.txt
fi
